  "sources": {
    "contracts/main/fee/FeeModule.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {IAccessController} from "../../interfaces/core/IAccessController.sol";
import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import {IVaultManagerConfig} from "../../interfaces/core/IVaultManagerConfig.sol";
import {IProtocolRegistry} from "../../interfaces/core/IProtocolRegistry.sol";
import {ITrancheVault} from "../../interfaces/core/ITrancheVault.sol";
import {ErrorLibrary} from "../../library/core/ErrorLibrary.sol";
import {IEventEmitter} from "../../interfaces/core/IEventEmitter.sol";

/**
 * @title FeeModule
 * @notice Handles protocol fee calculations and distributions for tranches
 * @dev This contract manages entry fees, exit fees, and performance fees
 *
 * Fee Structure:
 * - Senior Tranche (tid=0): Entry 0.1%, Exit 0.5% (within 30 days), Performance 0%
 * - Junior Tranche (tid=1): Entry 0%, Exit 1% (within 7 days), Performance 20%
 */
contract FeeModule is Initializable, UUPSUpgradeable, ReentrancyGuardUpgradeable, OwnableUpgradeable {
    using ErrorLibrary for *;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Access controller contract
    IAccessController public accessController;

    /// @notice Vault manager configuration contract
    IVaultManagerConfig public vaultManagerConfig;

    /// @notice Protocol registry contract
    IProtocolRegistry public protocolRegistry;

    /// @notice Event emitter contract
    IEventEmitter public eventEmitter;

    /// @notice Vault treasury address for receiving fees
    address public vaultTreasury;

    /// @notice High water mark for senior tranche performance fee calculations (1e18 base)
    uint256 public seniorHighWaterMark;

    /// @notice High water mark for junior tranche performance fee calculations (1e18 base)
    uint256 public juniorHighWaterMark;

    /// @notice Scale for fee calculations (100% = 10000 basis points)
    uint256 public constant FEE_SCALE = 1e4;

    /// @notice Scale for balance calculations
    uint256 public constant BALANCE_SCALE = 1e18;

    /******************************/
    /* Fee Parameters */
    /******************************/

    /// @notice Entry fee for senior tranche (in basis points, e.g., 10 = 0.1%)
    uint256 public seniorEntryFee;

    /// @notice Entry fee for junior tranche (in basis points, e.g., 0 = 0%)
    uint256 public juniorEntryFee;

    /// @notice Exit fee for senior tranche (in basis points, e.g., 50 = 0.5%)
    uint256 public seniorExitFee;

    /// @notice Exit fee for junior tranche (in basis points, e.g., 100 = 1%)
    uint256 public juniorExitFee;

    /// @notice Exit fee period for senior tranche (e.g., 30 days)
    uint256 public seniorExitFeePeriod;

    /// @notice Exit fee period for junior tranche (e.g., 7 days)
    uint256 public juniorExitFeePeriod;

    /// @notice Performance fee for senior tranche (in basis points, e.g., 0 = 0%)
    uint256 public seniorPerformanceFee;

    /// @notice Performance fee for junior tranche (in basis points, e.g., 2000 = 20%)
    uint256 public juniorPerformanceFee;

    /// @notice Senior rate per block (18 decimals), used for senior yield accrual
    uint256 public seniorRatePerBlock;

    /******************************/
    /* User Deposit Tracking */
    /******************************/

    /// @notice Tracks user's first deposit timestamp per tranche id
    /// @dev user => trancheId => timestamp
    mapping(address => mapping(uint256 => uint256)) public userDepositTimestamp;

    /// @notice Earliest execution time for a scheduled privileged operation
    mapping(bytes32 => uint256) public operationReadyAt;

    /// @dev Appended storage. A zero value on an upgraded proxy resolves to the default delay.
    uint256 private _privilegedChangeDelay;

    uint256 public constant DEFAULT_PRIVILEGED_CHANGE_DELAY = 2 days;
    uint256 public constant MIN_PRIVILEGED_CHANGE_DELAY = 1 minutes;
    uint256 public constant MAX_PRIVILEGED_CHANGE_DELAY = 30 days;
    uint256 private constant MAX_ENTRY_EXIT_FEE = 5000; // 50% in basis points
    uint256 private constant MAX_EXIT_FEE_PERIOD = 365 days;

    error TimelockOperationAlreadyScheduled(bytes32 operation, uint256 readyAt);
    error TimelockOperationNotScheduled(bytes32 operation);
    error TimelockOperationNotReady(bytes32 operation, uint256 readyAt);
    error UnsupportedTimelockSelector(bytes4 selector);
    error InvalidTimelockDelay(uint256 delay);

    /******************************/
    /* Fee Parameters Struct */
    /******************************/

    struct FeeParams {
        uint256 seniorEntryFee;
        uint256 juniorEntryFee;
        uint256 seniorExitFee;
        uint256 juniorExitFee;
        uint256 seniorExitFeePeriod;
        uint256 juniorExitFeePeriod;
        uint256 seniorPerformanceFee;
        uint256 juniorPerformanceFee;
    }

    /**
     * @notice Initializes the FeeModule contract with default fee values
     * @param _accessController Address of the access controller contract
     * @param _vaultManagerConfig Address of the vault manager config contract
     * @param _protocolRegistry Address of the protocol registry contract
     * @param _vaultTreasury Address of the vault treasury for receiving fees
     * @param _seniorRatePerBlock Senior rate per block in 18 decimals (e.g. 0.001e18 = 0.1% per block)
     * @custom:throws InvalidAddress if any of the input addresses is zero
     */
    function initialize(
        address _accessController,
        address _vaultManagerConfig,
        address _protocolRegistry,
        address _vaultTreasury,
        uint256 _seniorRatePerBlock
    ) public virtual initializer {
        _initializeFeeModule(
            _accessController,
            _vaultManagerConfig,
            _protocolRegistry,
            _vaultTreasury,
            _seniorRatePerBlock,
            FeeParams({
                seniorEntryFee: 10,
                juniorEntryFee: 0,
                seniorExitFee: 50,
                juniorExitFee: 100,
                seniorExitFeePeriod: 30 days,
                juniorExitFeePeriod: 7 days,
                seniorPerformanceFee: 0,
                juniorPerformanceFee: 2000
            })
        );
    }

    function _initializeFeeModule(
        address _accessController,
        address _vaultManagerConfig,
        address _protocolRegistry,
        address _vaultTreasury,
        uint256 _seniorRatePerBlock,
        FeeParams memory _feeParams
    ) internal onlyInitializing {
        if (_accessController == address(0)) revert ErrorLibrary.InvalidAddress();
        if (_vaultManagerConfig == address(0)) revert ErrorLibrary.InvalidAddress();
        if (_protocolRegistry == address(0)) revert ErrorLibrary.InvalidAddress();
        if (_vaultTreasury == address(0)) revert ErrorLibrary.InvalidAddress();

        __UUPSUpgradeable_init();
        __Ownable_init();
        __ReentrancyGuard_init();

        accessController = IAccessController(_accessController);
        vaultManagerConfig = IVaultManagerConfig(_vaultManagerConfig);
        protocolRegistry = IProtocolRegistry(_protocolRegistry);
        eventEmitter = IEventEmitter(protocolRegistry.getEventEmitter());
        vaultTreasury = _vaultTreasury;
        seniorRatePerBlock = _seniorRatePerBlock;
        _privilegedChangeDelay = DEFAULT_PRIVILEGED_CHANGE_DELAY;

        seniorEntryFee = _feeParams.seniorEntryFee;
        juniorEntryFee = _feeParams.juniorEntryFee;
        seniorExitFee = _feeParams.seniorExitFee;
        juniorExitFee = _feeParams.juniorExitFee;
        seniorExitFeePeriod = _feeParams.seniorExitFeePeriod;
        juniorExitFeePeriod = _feeParams.juniorExitFeePeriod;
        seniorPerformanceFee = _feeParams.seniorPerformanceFee;
        juniorPerformanceFee = _feeParams.juniorPerformanceFee;

        // Initialize high water marks
        seniorHighWaterMark = BALANCE_SCALE;
        juniorHighWaterMark = BALANCE_SCALE;
    }

    /******************************/
    /* Modifiers */
    /******************************/

    /**
     * @notice Modifier to ensure caller has vault manager role
     * @custom:throws CallerIsNotVaultManager if caller doesn't have vault manager role
     */
    modifier onlyVaultManager() {
        if (!accessController.hasRole(keccak256("TRANCHE_VAULT_MANAGER_ROLE"), msg.sender))
            revert ErrorLibrary.CallerIsNotVaultManager();
        _;
    }

    /**
     * @notice Modifier to ensure caller is a tranche vault
     * @custom:throws CallerIsNotTrancheVault if caller is not a tranche vault
     */
    modifier onlyTrancheVault() {
        if (!accessController.hasRole(keccak256("TRANCHE_VAULT_ROLE"), msg.sender))
            revert ErrorLibrary.CallerIsNotTrancheVault();
        _;
    }

    /******************************/
    /* Entry Fee Functions */
    /******************************/

    /**
     * @notice Calculates entry fee for senior tranche deposit
     * @param amount Amount being deposited
     * @return feeAmount The fee amount to deduct
     * @return amountAfterFee The amount after fee deduction
     */
    function chargeEntryFee(
        uint256 trancheId,
        uint256 amount
    ) external onlyTrancheVault returns (uint256 feeAmount, uint256 amountAfterFee) {
        (feeAmount, amountAfterFee) = _calculateEntryFee(trancheId, amount);
        _getEventEmitter().entryFeeChargedEvent(msg.sender, trancheId, amount, feeAmount, amountAfterFee);
    }

    /**
     * @notice Calculates entry fee for a deposit (generic)
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @param amount Amount being deposited
     * @return feeAmount The fee amount to deduct
     * @return amountAfterFee The amount after fee deduction
     */
    function calculateEntryFee(
        uint256 trancheId,
        uint256 amount
    ) external view returns (uint256 feeAmount, uint256 amountAfterFee) {
        return _calculateEntryFee(trancheId, amount);
    }

    /**
     * @notice Internal function to calculate entry fee
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @param amount Amount being deposited
     * @return feeAmount The fee amount to deduct
     * @return amountAfterFee The amount after fee deduction
     */
    function _calculateEntryFee(
        uint256 trancheId,
        uint256 amount
    ) internal view returns (uint256 feeAmount, uint256 amountAfterFee) {
        _validateTrancheId(trancheId);
        uint256 feeRate = trancheId == 0 ? seniorEntryFee : juniorEntryFee;

        // If fee rate is 0, no fee applies
        if (feeRate == 0) {
            return (0, amount);
        }

        feeAmount = (amount * feeRate) / FEE_SCALE;
        amountAfterFee = amount - feeAmount;
    }

    /**
     * @notice Records user deposit timestamp for exit fee calculations
     * @param user Address of the user
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @dev Only callable by tranche vault
     * @dev Updates to latest deposit timestamp on each deposit
     */
    function recordDeposit(address user, uint256 trancheId) external onlyTrancheVault {
        _validateTrancheId(trancheId);
        uint256 oldTimestamp = userDepositTimestamp[user][trancheId];
        userDepositTimestamp[user][trancheId] = block.timestamp;
        _getEventEmitter().depositTimestampUpdatedEvent(user, trancheId, oldTimestamp, block.timestamp);
    }

    function recordTransfer(
        address from,
        address to,
        uint256 trancheId,
        uint256 amount,
        uint256 recipientBalance
    ) external onlyTrancheVault {
        _validateTrancheId(trancheId);
        if (to == address(0) || recipientBalance < amount) revert ErrorLibrary.InvalidAmount();
        uint256 sourceTimestamp = userDepositTimestamp[from][trancheId];
        if (sourceTimestamp == 0) sourceTimestamp = block.timestamp;
        uint256 previousBalance = recipientBalance - amount;
        uint256 oldTimestamp = userDepositTimestamp[to][trancheId];
        if (previousBalance == 0) {
            userDepositTimestamp[to][trancheId] = sourceTimestamp;
            _getEventEmitter().depositTimestampUpdatedEvent(to, trancheId, oldTimestamp, sourceTimestamp);
            return;
        }
        uint256 recipientTimestamp = userDepositTimestamp[to][trancheId];
        if (recipientTimestamp == 0) recipientTimestamp = block.timestamp;
        userDepositTimestamp[to][trancheId] =
            ((recipientTimestamp * previousBalance) + (sourceTimestamp * amount)) /
            recipientBalance;
        _getEventEmitter().depositTimestampUpdatedEvent(
            to,
            trancheId,
            oldTimestamp,
            userDepositTimestamp[to][trancheId]
        );
    }

    /******************************/
    /* Exit Fee Functions */
    /******************************/

    /**
     * @notice Calculates exit fee for senior tranche withdrawal
     * @param user Address of the user
     * @param amount Amount being withdrawn
     * @return feeAmount The fee amount to deduct
     * @return amountAfterFee The amount after fee deduction
     */
    function calculateSeniorExitFee(
        address user,
        uint256 amount
    ) external view returns (uint256 feeAmount, uint256 amountAfterFee) {
        return _calculateExitFee(user, 0, amount);
    }

    /**
     * @notice Calculates exit fee for junior tranche withdrawal
     * @param user Address of the user
     * @param amount Amount being withdrawn
     * @return feeAmount The fee amount to deduct
     * @return amountAfterFee The amount after fee deduction
     */
    function calculateJuniorExitFee(
        address user,
        uint256 amount
    ) external view returns (uint256 feeAmount, uint256 amountAfterFee) {
        return _calculateExitFee(user, 1, amount);
    }

    /**
     * @notice Calculates an exit fee denominated in the withdrawn currency
     * @param user Address of the user
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @param amount Gross currency amount being withdrawn
     * @return feeAmount The fee amount to deduct
     * @return amountAfterFee The amount after fee deduction
     */
    function calculateExitFee(
        address user,
        uint256 trancheId,
        uint256 amount
    ) external view returns (uint256 feeAmount, uint256 amountAfterFee) {
        return _calculateExitFee(user, trancheId, amount);
    }

    /**
     * @notice Calculates an exit fee and emits an auditable record of the fee charged
     * @dev The tranche vault performs the currency split atomically after this call
     */
    function chargeExitFee(
        address user,
        uint256 trancheId,
        uint256 amount
    ) external onlyTrancheVault returns (uint256 feeAmount, uint256 amountAfterFee) {
        (feeAmount, amountAfterFee) = _calculateExitFee(user, trancheId, amount);
        _getEventEmitter().exitFeeChargedEvent(msg.sender, user, trancheId, amount, feeAmount, amountAfterFee);
    }

    /**
     * @notice Deprecated compatibility helper; use calculateExitFee for currency fees
     * @param user Address of the user
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @param receiptTokenAmount Amount of receipt tokens being withdrawn
     * @return feeAmount The fee amount in receipt tokens to transfer to treasury
     * @return amountAfterFee The receipt token amount after fee deduction (to be burned)
     */
    function calculateExitFeeOnReceiptTokens(
        address user,
        uint256 trancheId,
        uint256 receiptTokenAmount
    ) external view returns (uint256 feeAmount, uint256 amountAfterFee) {
        return _calculateExitFee(user, trancheId, receiptTokenAmount);
    }

    /**
     * @notice Internal function to calculate exit fee
     * @param user Address of the user
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @param amount Amount being withdrawn
     * @return feeAmount The fee amount to deduct
     * @return amountAfterFee The amount after fee deduction
     */
    function _calculateExitFee(
        address user,
        uint256 trancheId,
        uint256 amount
    ) internal view returns (uint256 feeAmount, uint256 amountAfterFee) {
        _validateTrancheId(trancheId);
        uint256 feeRate;
        uint256 feePeriod;

        if (trancheId == 0) {
            feeRate = seniorExitFee;
            feePeriod = seniorExitFeePeriod;
        } else {
            feeRate = juniorExitFee;
            feePeriod = juniorExitFeePeriod;
        }

        // If fee rate is 0, no exit fee applies
        if (feeRate == 0) {
            return (0, amount);
        }

        // Check if user is still within the exit fee period
        uint256 depositTime = userDepositTimestamp[user][trancheId];

        // If no deposit recorded, no exit fee applies
        if (depositTime == 0) {
            return (0, amount);
        }

        // Check if exit fee period has passed
        if (block.timestamp >= depositTime + feePeriod) {
            return (0, amount);
        }

        // Calculate exit fee
        feeAmount = (amount * feeRate) / FEE_SCALE;
        amountAfterFee = amount - feeAmount;
    }

    /**
     * @notice Checks if exit fee applies for senior tranche
     * @param user Address of the user
     * @return applies Whether exit fee applies
     * @return feeRate The exit fee rate in basis points
     * @return timeRemaining Time remaining in fee period (0 if period passed)
     */
    function getSeniorExitFeeStatus(
        address user
    ) external view returns (bool applies, uint256 feeRate, uint256 timeRemaining) {
        return _getExitFeeStatus(user, 0);
    }

    /**
     * @notice Checks if exit fee applies for junior tranche
     * @param user Address of the user
     * @return applies Whether exit fee applies
     * @return feeRate The exit fee rate in basis points
     * @return timeRemaining Time remaining in fee period (0 if period passed)
     */
    function getJuniorExitFeeStatus(
        address user
    ) external view returns (bool applies, uint256 feeRate, uint256 timeRemaining) {
        return _getExitFeeStatus(user, 1);
    }

    /**
     * @notice Checks if exit fee applies for a user (generic)
     * @param user Address of the user
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @return applies Whether exit fee applies
     * @return feeRate The exit fee rate in basis points
     * @return timeRemaining Time remaining in fee period (0 if period passed)
     */
    function getExitFeeStatus(
        address user,
        uint256 trancheId
    ) external view returns (bool applies, uint256 feeRate, uint256 timeRemaining) {
        return _getExitFeeStatus(user, trancheId);
    }

    /**
     * @notice Internal function to get exit fee status
     * @param user Address of the user
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @return applies Whether exit fee applies
     * @return feeRate The exit fee rate in basis points
     * @return timeRemaining Time remaining in fee period (0 if period passed)
     */
    function _getExitFeeStatus(
        address user,
        uint256 trancheId
    ) internal view returns (bool applies, uint256 feeRate, uint256 timeRemaining) {
        _validateTrancheId(trancheId);
        uint256 feePeriod;

        if (trancheId == 0) {
            feeRate = seniorExitFee;
            feePeriod = seniorExitFeePeriod;
        } else {
            feeRate = juniorExitFee;
            feePeriod = juniorExitFeePeriod;
        }

        // If fee rate is 0, exit fee never applies
        if (feeRate == 0) {
            return (false, 0, 0);
        }

        uint256 depositTime = userDepositTimestamp[user][trancheId];

        // If no deposit recorded, exit fee doesn't apply
        if (depositTime == 0) {
            return (false, feeRate, 0);
        }

        uint256 feeEndTime = depositTime + feePeriod;

        // If fee period has passed, exit fee doesn't apply
        if (block.timestamp >= feeEndTime) {
            return (false, feeRate, 0);
        }

        applies = true;
        timeRemaining = feeEndTime - block.timestamp;
    }

    /**
     * @notice Resets user deposit timestamp on full withdrawal
     * @param user Address of the user
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @dev Only callable by tranche vault
     */
    function resetUserDepositTimestamp(address user, uint256 trancheId) external onlyTrancheVault {
        _validateTrancheId(trancheId);
        uint256 oldTimestamp = userDepositTimestamp[user][trancheId];
        userDepositTimestamp[user][trancheId] = 0;
        _getEventEmitter().depositTimestampUpdatedEvent(user, trancheId, oldTimestamp, 0);
    }

    /******************************/
    /* Performance Fee Functions */
    /******************************/

    /**
     * @notice Charges performance fee for senior tranche based on profits above HWM
     * @param trancheVault Address of the tranche vault
     * @param seniorVaultInvestments Current senior vault investments
     * @param seniorTokenSupply Total supply of senior tokens
     * @return totalFee The total performance fee charged
     */
    function chargeSeniorPerformanceFee(
        address trancheVault,
        uint256 seniorVaultInvestments,
        uint256 seniorTokenSupply
    ) external nonReentrant onlyTrancheVault returns (uint256) {
        return _chargePerformanceFee(trancheVault, 0, seniorVaultInvestments, seniorTokenSupply);
    }

    /**
     * @notice Charges performance fee for junior tranche based on profits above HWM
     * @param trancheVault Address of the tranche vault
     * @param juniorVaultInvestments Current junior vault investments
     * @param juniorTokenSupply Total supply of junior tokens
     * @return totalFee The total performance fee charged
     */
    function chargeJuniorPerformanceFee(
        address trancheVault,
        uint256 juniorVaultInvestments,
        uint256 juniorTokenSupply
    ) external nonReentrant onlyTrancheVault returns (uint256) {
        return _chargePerformanceFee(trancheVault, 1, juniorVaultInvestments, juniorTokenSupply);
    }

    /**
     * @notice Internal function to charge performance fee for a tranche
     * @param trancheVault Address of the tranche vault
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @param vaultInvestments Current vault investments for the tranche
     * @param tokenSupply Total supply of tranche tokens
     * @return totalFee The total performance fee charged
     */
    function _chargePerformanceFee(
        address trancheVault,
        uint256 trancheId,
        uint256 vaultInvestments,
        uint256 tokenSupply
    ) internal returns (uint256) {
        // If no investments or no tokens, nothing to charge
        if (vaultInvestments == 0 || tokenSupply == 0) {
            return 0;
        }

        // Get the appropriate performance fee and HWM based on tranche
        uint256 performanceFee = trancheId == 0 ? seniorPerformanceFee : juniorPerformanceFee;

        // If performance fee is 0, skip
        if (performanceFee == 0) {
            return 0;
        }

        uint256 currentHwm = trancheId == 0 ? seniorHighWaterMark : juniorHighWaterMark;
        uint256 currentRate = (vaultInvestments * BALANCE_SCALE) / tokenSupply;

        // Only charge if above HWM
        if (currentRate <= currentHwm) {
            return 0;
        }

        uint256 totalProfit = ((currentRate - currentHwm) * tokenSupply) / BALANCE_SCALE;
        uint256 totalFee = (totalProfit * performanceFee) / FEE_SCALE;

        // If fee is zero or would cause division issues, skip
        if (totalFee == 0 || totalFee >= vaultInvestments) {
            return 0;
        }

        // Update HWM to the POST-fee rate. The fee is paid by minting shares worth
        // exactly totalFee, which lowers the rate to (investments - fee) / supply.
        // Setting the HWM to the pre-fee currentRate instead left that fee-sized
        // gap below the mark, so the next gain of the same size was never charged
        // and the effective take was fee / (1 + fee): ~16.7% on a 20% setting.
        uint256 newHwm = ((vaultInvestments - totalFee) * BALANCE_SCALE) / tokenSupply;
        if (trancheId == 0) {
            seniorHighWaterMark = newHwm;
        } else {
            juniorHighWaterMark = newHwm;
        }

        // Calculate mint amounts
        uint256 mintAmountTotal = (totalFee * tokenSupply) / (vaultInvestments - totalFee);
        uint256 mintAmountStrategyManager = (mintAmountTotal * vaultManagerConfig.getVaultManagerFee()) / FEE_SCALE;

        // Emit performance fee charged event through event emitter
        _getEventEmitter().performanceFeeChargedEvent(trancheVault, trancheId, totalProfit, totalFee, newHwm);

        // Mint fees to treasury and strategy manager (using appropriate tranche token)
        uint256 protocolTreasuryAmount = mintAmountTotal - mintAmountStrategyManager;
        _mintFee(trancheVault, trancheId, vaultTreasury, protocolTreasuryAmount);
        _mintFee(trancheVault, trancheId, vaultManagerConfig.getUserTreasury(), mintAmountStrategyManager);

        return totalFee;
    }

    /**
     * @notice Legacy function - Charges performance fee for junior tranche
     * @param trancheVault Address of the tranche vault
     * @param juniorVaultInvestments Current junior vault investments
     * @param juniorTokenSupply Total supply of junior tokens
     * @return totalFee The total performance fee charged
     * @dev Maintained for backward compatibility, calls chargeJuniorPerformanceFee internally
     */
    function chargeProtocolFee(
        address trancheVault,
        uint256, // currentStrategyBalance - unused, kept for backward compatibility
        uint256 juniorVaultInvestments,
        uint256 juniorTokenSupply
    ) external nonReentrant onlyTrancheVault returns (uint256) {
        // For backward compatibility, this charges junior performance fee
        return _chargePerformanceFee(trancheVault, 1, juniorVaultInvestments, juniorTokenSupply);
    }

    /**
     * @notice Internal function to mint senior fee tokens
     * @param trancheVault Address of the tranche vault
     * @param to Address to receive the minted tokens
     * @param mintAmount Amount of tokens to mint
     */
    function _mintSeniorFee(address trancheVault, address to, uint256 mintAmount) internal {
        if (mintAmount == 0) return;
        if (to == address(0)) revert ErrorLibrary.InvalidAddress();

        ITrancheVault(trancheVault).mintSeniorTokenFee(to, mintAmount);

        // Emit fee minted event through event emitter
        _getEventEmitter().feeMintedEvent(trancheVault, to, mintAmount);
    }

    /**
     * @notice Internal function to mint junior fee tokens
     * @param trancheVault Address of the tranche vault
     * @param to Address to receive the minted tokens
     * @param mintAmount Amount of tokens to mint
     */
    function _mintJuniorFee(address trancheVault, address to, uint256 mintAmount) internal {
        if (mintAmount == 0) return;
        if (to == address(0)) revert ErrorLibrary.InvalidAddress();

        ITrancheVault(trancheVault).mintJuniorTokenFee(to, mintAmount);

        // Emit fee minted event through event emitter
        _getEventEmitter().feeMintedEvent(trancheVault, to, mintAmount);
    }

    /**
     * @notice Internal function to mint fee tokens based on tranche
     * @param trancheVault Address of the tranche vault
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @param to Address to receive the minted tokens
     * @param mintAmount Amount of tokens to mint
     */
    function _mintFee(address trancheVault, uint256 trancheId, address to, uint256 mintAmount) internal {
        if (trancheId == 0) {
            _mintSeniorFee(trancheVault, to, mintAmount);
        } else {
            _mintJuniorFee(trancheVault, to, mintAmount);
        }
    }

    /******************************/
    /* Admin Functions */
    /******************************/

    /**
     * @notice Executes a previously scheduled update of all fee parameters
     * @param _feeParams New fee parameters
     * @dev Call scheduleFeeChange with this selector and abi.encode(_feeParams), then wait for the delay
     */
    function setFeeParams(FeeParams calldata _feeParams) external onlyVaultManager {
        _consumeTimelockedChange(msg.sig, abi.encode(_feeParams));
        FeeParams memory oldParams = _getFeeParams();
        _setFeeParams(_feeParams);
        _emitFeeParameterUpdates(oldParams, _feeParams);
        _getEventEmitter().feeParametersUpdatedEvent(
            _feeParams.seniorEntryFee,
            _feeParams.juniorEntryFee,
            _feeParams.seniorExitFee,
            _feeParams.juniorExitFee,
            _feeParams.seniorExitFeePeriod,
            _feeParams.juniorExitFeePeriod,
            _feeParams.seniorPerformanceFee,
            _feeParams.juniorPerformanceFee
        );
    }

    /**
     * @notice Internal function to set fee parameters
     * @param _feeParams Fee parameters to set
     */
    function _setFeeParams(FeeParams calldata _feeParams) internal {
        if (_feeParams.seniorEntryFee > MAX_ENTRY_EXIT_FEE) revert ErrorLibrary.InvalidFee();
        if (_feeParams.juniorEntryFee > MAX_ENTRY_EXIT_FEE) revert ErrorLibrary.InvalidFee();
        if (_feeParams.seniorExitFee > MAX_ENTRY_EXIT_FEE) revert ErrorLibrary.InvalidFee();
        if (_feeParams.juniorExitFee > MAX_ENTRY_EXIT_FEE) revert ErrorLibrary.InvalidFee();
        if (_feeParams.seniorExitFeePeriod > MAX_EXIT_FEE_PERIOD) revert ErrorLibrary.InvalidFee();
        if (_feeParams.juniorExitFeePeriod > MAX_EXIT_FEE_PERIOD) revert ErrorLibrary.InvalidFee();
        if (_feeParams.seniorPerformanceFee > 5000) revert ErrorLibrary.InvalidFee();
        if (_feeParams.juniorPerformanceFee > 5000) revert ErrorLibrary.InvalidFee();

        seniorEntryFee = _feeParams.seniorEntryFee;
        juniorEntryFee = _feeParams.juniorEntryFee;
        seniorExitFee = _feeParams.seniorExitFee;
        juniorExitFee = _feeParams.juniorExitFee;
        seniorExitFeePeriod = _feeParams.seniorExitFeePeriod;
        juniorExitFeePeriod = _feeParams.juniorExitFeePeriod;
        seniorPerformanceFee = _feeParams.seniorPerformanceFee;
        juniorPerformanceFee = _feeParams.juniorPerformanceFee;
    }

    /**
     * @notice Executes a scheduled senior tranche entry-fee update
     * @param _fee New fee in basis points
     */
    function setSeniorEntryFee(uint256 _fee) external onlyVaultManager {
        if (_fee > MAX_ENTRY_EXIT_FEE) revert ErrorLibrary.InvalidFee();
        _consumeTimelockedChange(msg.sig, abi.encode(_fee));
        _getEventEmitter().feeParameterUpdatedEvent(msg.sig, seniorEntryFee, _fee);
        seniorEntryFee = _fee;
    }

    /**
     * @notice Executes a scheduled junior tranche entry-fee update
     * @param _fee New fee in basis points
     */
    function setJuniorEntryFee(uint256 _fee) external onlyVaultManager {
        if (_fee > MAX_ENTRY_EXIT_FEE) revert ErrorLibrary.InvalidFee();
        _consumeTimelockedChange(msg.sig, abi.encode(_fee));
        _getEventEmitter().feeParameterUpdatedEvent(msg.sig, juniorEntryFee, _fee);
        juniorEntryFee = _fee;
    }

    /**
     * @notice Executes a scheduled senior tranche exit-fee update
     * @param _fee New fee in basis points
     */
    function setSeniorExitFee(uint256 _fee) external onlyVaultManager {
        if (_fee > MAX_ENTRY_EXIT_FEE) revert ErrorLibrary.InvalidFee();
        _consumeTimelockedChange(msg.sig, abi.encode(_fee));
        _getEventEmitter().feeParameterUpdatedEvent(msg.sig, seniorExitFee, _fee);
        seniorExitFee = _fee;
    }

    /**
     * @notice Executes a scheduled junior tranche exit-fee update
     * @param _fee New fee in basis points
     */
    function setJuniorExitFee(uint256 _fee) external onlyVaultManager {
        if (_fee > MAX_ENTRY_EXIT_FEE) revert ErrorLibrary.InvalidFee();
        _consumeTimelockedChange(msg.sig, abi.encode(_fee));
        _getEventEmitter().feeParameterUpdatedEvent(msg.sig, juniorExitFee, _fee);
        juniorExitFee = _fee;
    }

    /**
     * @notice Executes a scheduled senior tranche exit-fee-period update
     * @param _period New period in seconds
     */
    function setSeniorExitFeePeriod(uint256 _period) external onlyVaultManager {
        if (_period > MAX_EXIT_FEE_PERIOD) revert ErrorLibrary.InvalidFee();
        _consumeTimelockedChange(msg.sig, abi.encode(_period));
        _getEventEmitter().feeParameterUpdatedEvent(msg.sig, seniorExitFeePeriod, _period);
        seniorExitFeePeriod = _period;
    }

    /**
     * @notice Executes a scheduled junior tranche exit-fee-period update
     * @param _period New period in seconds
     */
    function setJuniorExitFeePeriod(uint256 _period) external onlyVaultManager {
        if (_period > MAX_EXIT_FEE_PERIOD) revert ErrorLibrary.InvalidFee();
        _consumeTimelockedChange(msg.sig, abi.encode(_period));
        _getEventEmitter().feeParameterUpdatedEvent(msg.sig, juniorExitFeePeriod, _period);
        juniorExitFeePeriod = _period;
    }

    /**
     * @notice Executes a scheduled senior tranche performance-fee update
     * @param _fee New fee in basis points
     */
    function setSeniorPerformanceFee(uint256 _fee) external onlyVaultManager {
        if (_fee > 5000) revert ErrorLibrary.InvalidFee();
        _consumeTimelockedChange(msg.sig, abi.encode(_fee));
        _getEventEmitter().feeParameterUpdatedEvent(msg.sig, seniorPerformanceFee, _fee);
        seniorPerformanceFee = _fee;
    }

    /**
     * @notice Executes a scheduled junior tranche performance-fee update
     * @param _fee New fee in basis points
     */
    function setJuniorPerformanceFee(uint256 _fee) external onlyVaultManager {
        if (_fee > 5000) revert ErrorLibrary.InvalidFee();
        _consumeTimelockedChange(msg.sig, abi.encode(_fee));
        _getEventEmitter().feeParameterUpdatedEvent(msg.sig, juniorPerformanceFee, _fee);
        juniorPerformanceFee = _fee;
    }

    /**
     * @notice Executes a scheduled vault-treasury update
     * @param _vaultTreasury New vault treasury address
     */
    function setVaultTreasury(address _vaultTreasury) external onlyVaultManager {
        if (_vaultTreasury == address(0)) revert ErrorLibrary.InvalidAddress();
        _consumeTimelockedChange(msg.sig, abi.encode(_vaultTreasury));
        _getEventEmitter().vaultTreasuryUpdatedEvent(vaultTreasury, _vaultTreasury);
        vaultTreasury = _vaultTreasury;
    }

    /**
     * @notice Executes a scheduled senior-rate-per-block update
     * @param _seniorRatePerBlock New rate per block (e.g. 0.001e18 = 0.1% per block)
     */
    function updateRatePerBlock(uint256 _seniorRatePerBlock) external onlyVaultManager {
        if (_seniorRatePerBlock == 0) revert ErrorLibrary.InvalidFee();
        _consumeTimelockedChange(msg.sig, abi.encode(_seniorRatePerBlock));
        _getEventEmitter().seniorRatePerBlockUpdatedEvent(seniorRatePerBlock, _seniorRatePerBlock);
        seniorRatePerBlock = _seniorRatePerBlock;
    }

    /**
     * @notice Explicitly schedules a supported fee change
     * @param selector Selector of the setter that will execute the change
     * @param parameters ABI-encoded setter arguments (without the selector)
     */
    function scheduleFeeChange(
        bytes4 selector,
        bytes calldata parameters
    ) external onlyVaultManager returns (bytes32 operation, uint256 readyAt) {
        if (!_isSupportedTimelockSelector(selector)) revert UnsupportedTimelockSelector(selector);
        return _scheduleTimelockedChange(selector, parameters);
    }

    /** @notice Cancels a scheduled fee change before execution */
    function cancelFeeChange(bytes32 operation) external onlyVaultManager {
        uint256 readyAt = operationReadyAt[operation];
        if (readyAt == 0) revert TimelockOperationNotScheduled(operation);
        delete operationReadyAt[operation];
        _getEventEmitter().privilegedChangeCancelledEvent(operation);
    }

    /**
     * @notice Sets the privileged-change delay immediately.
     * @dev The delay itself is deliberately NOT timelocked. Timelocking it meant
     *      that shortening the window first cost a full window — 2 days to make
     *      the next change take 1 minute — which made the delay impractical to
     *      tune. The fee setters it governs remain timelocked; only this knob is
     *      immediate.
     *
     *      Note the tradeoff this accepts: the vault manager can set the delay to
     *      MIN_PRIVILEGED_CHANGE_DELAY and then schedule a fee change that
     *      matures that quickly, so the timelock now bounds how much notice
     *      depositors get only as far as the vault manager chooses to give it.
     *      MIN_PRIVILEGED_CHANGE_DELAY is the floor that still applies.
     * @param newDelay New delay in seconds; must satisfy the MIN/MAX bounds.
     */
    function setPrivilegedChangeDelay(uint256 newDelay) external onlyVaultManager {
        _validateTimelockDelay(newDelay);
        uint256 oldDelay = getPrivilegedChangeDelay();
        _privilegedChangeDelay = newDelay;
        _getEventEmitter().privilegedChangeDelayUpdatedEvent(oldDelay, newDelay);
    }

    function getPrivilegedChangeDelay() public view returns (uint256) {
        uint256 configuredDelay = _privilegedChangeDelay;
        return configuredDelay == 0 ? DEFAULT_PRIVILEGED_CHANGE_DELAY : configuredDelay;
    }

    function getFeeChangeOperationId(bytes4 selector, bytes calldata parameters) external pure returns (bytes32) {
        return _operationId(selector, parameters);
    }

    function _scheduleTimelockedChange(
        bytes4 selector,
        bytes memory parameters
    ) internal returns (bytes32 operation, uint256 readyAt) {
        operation = _operationId(selector, parameters);
        readyAt = operationReadyAt[operation];
        if (readyAt != 0) revert TimelockOperationAlreadyScheduled(operation, readyAt);
        readyAt = block.timestamp + getPrivilegedChangeDelay();
        operationReadyAt[operation] = readyAt;
        _getEventEmitter().privilegedChangeScheduledEvent(operation, readyAt);
    }

    function _consumeTimelockedChange(bytes4 selector, bytes memory parameters) internal {
        bytes32 operation = _operationId(selector, parameters);
        uint256 readyAt = operationReadyAt[operation];
        if (readyAt == 0) revert TimelockOperationNotScheduled(operation);
        if (block.timestamp < readyAt) revert TimelockOperationNotReady(operation, readyAt);
        delete operationReadyAt[operation];
        _getEventEmitter().privilegedChangeExecutedEvent(operation);
    }

    function _operationId(bytes4 selector, bytes memory parameters) internal pure returns (bytes32) {
        return keccak256(abi.encode(selector, parameters));
    }

    function _isSupportedTimelockSelector(bytes4 selector) internal pure returns (bool) {
        return
            selector == this.setFeeParams.selector ||
            selector == this.setSeniorEntryFee.selector ||
            selector == this.setJuniorEntryFee.selector ||
            selector == this.setSeniorExitFee.selector ||
            selector == this.setJuniorExitFee.selector ||
            selector == this.setSeniorExitFeePeriod.selector ||
            selector == this.setJuniorExitFeePeriod.selector ||
            selector == this.setSeniorPerformanceFee.selector ||
            selector == this.setJuniorPerformanceFee.selector ||
            selector == this.setVaultTreasury.selector ||
            selector == this.updateRatePerBlock.selector;
    }

    function _validateTimelockDelay(uint256 delay_) internal pure {
        if (delay_ < MIN_PRIVILEGED_CHANGE_DELAY || delay_ > MAX_PRIVILEGED_CHANGE_DELAY) {
            revert InvalidTimelockDelay(delay_);
        }
    }

    function _validateTrancheId(uint256 trancheId) internal pure {
        if (trancheId > 1) revert ErrorLibrary.TrancheIdInvalid();
    }

    function _getFeeParams() internal view returns (FeeParams memory params) {
        params = FeeParams({
            seniorEntryFee: seniorEntryFee,
            juniorEntryFee: juniorEntryFee,
            seniorExitFee: seniorExitFee,
            juniorExitFee: juniorExitFee,
            seniorExitFeePeriod: seniorExitFeePeriod,
            juniorExitFeePeriod: juniorExitFeePeriod,
            seniorPerformanceFee: seniorPerformanceFee,
            juniorPerformanceFee: juniorPerformanceFee
        });
    }

    function _emitFeeParameterUpdates(FeeParams memory oldParams, FeeParams calldata newParams) internal {
        IEventEmitter emitter = _getEventEmitter();
        emitter.feeParameterUpdatedEvent(
            this.setSeniorEntryFee.selector,
            oldParams.seniorEntryFee,
            newParams.seniorEntryFee
        );
        emitter.feeParameterUpdatedEvent(
            this.setJuniorEntryFee.selector,
            oldParams.juniorEntryFee,
            newParams.juniorEntryFee
        );
        emitter.feeParameterUpdatedEvent(this.setSeniorExitFee.selector, oldParams.seniorExitFee, newParams.seniorExitFee);
        emitter.feeParameterUpdatedEvent(this.setJuniorExitFee.selector, oldParams.juniorExitFee, newParams.juniorExitFee);
        emitter.feeParameterUpdatedEvent(
            this.setSeniorExitFeePeriod.selector,
            oldParams.seniorExitFeePeriod,
            newParams.seniorExitFeePeriod
        );
        emitter.feeParameterUpdatedEvent(
            this.setJuniorExitFeePeriod.selector,
            oldParams.juniorExitFeePeriod,
            newParams.juniorExitFeePeriod
        );
        emitter.feeParameterUpdatedEvent(
            this.setSeniorPerformanceFee.selector,
            oldParams.seniorPerformanceFee,
            newParams.seniorPerformanceFee
        );
        emitter.feeParameterUpdatedEvent(
            this.setJuniorPerformanceFee.selector,
            oldParams.juniorPerformanceFee,
            newParams.juniorPerformanceFee
        );
    }

    function _getEventEmitter() internal view returns (IEventEmitter) {
        return IEventEmitter(protocolRegistry.getEventEmitter());
    }

    /******************************/
    /* View Functions */
    /******************************/

    /**
     * @notice Returns all fee parameters
     * @return params Current fee parameters
     */
    function getFeeParams() external view returns (FeeParams memory params) {
        return _getFeeParams();
    }

    /**
     * @notice Returns user deposit timestamp for a specific tranche
     * @param user Address of the user
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @return timestamp User's first deposit timestamp
     */
    function getUserDepositTimestamp(address user, uint256 trancheId) external view returns (uint256) {
        _validateTrancheId(trancheId);
        return userDepositTimestamp[user][trancheId];
    }

    /**
     * @notice Returns high water mark for senior tranche
     * @return hwm High water mark value (1e18 base)
     */
    function getSeniorHighWaterMark() external view returns (uint256) {
        return seniorHighWaterMark;
    }

    /**
     * @notice Returns high water mark for junior tranche
     * @return hwm High water mark value (1e18 base)
     */
    function getJuniorHighWaterMark() external view returns (uint256) {
        return juniorHighWaterMark;
    }

    /**
     * @notice Returns high water mark for a specific tranche
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @return hwm High water mark value (1e18 base)
     */
    function getHighWaterMark(uint256 trancheId) external view returns (uint256) {
        _validateTrancheId(trancheId);
        return trancheId == 0 ? seniorHighWaterMark : juniorHighWaterMark;
    }

    /**
     * @notice Returns senior rate per block (18 decimals)
     * @return rate Senior rate per block
     */
    function getSeniorRatePerBlock() external view returns (uint256) {
        return seniorRatePerBlock;
    }

    /**
     * @notice Recovers ETH accidentally sent to this contract
     * @param _to Address to send recovered ETH to
     */
    function recoverETH(address payable _to) external onlyVaultManager {
        if (_to == address(0)) revert ErrorLibrary.InvalidAddress();
        (bool success, ) = _to.call{value: address(this).balance}("");
        if (!success) revert ErrorLibrary.TransferFailed();
    }

    receive() external payable {}
    fallback() external payable {}

    /**
     * @notice Authorizes contract upgrade
     * @param newImplementation Address of the new implementation
     */
    function _authorizeUpgrade(address newImplementation) internal virtual override onlyOwner {
        if (newImplementation == address(0)) revert ErrorLibrary.InvalidAddress();
    }
}
"
    },
    "contracts/interfaces/core/IEventEmitter.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

interface IEventEmitter {
    // Protocol Registry Event Functions
    function protocolPauseUpdatedEvent(bool newState) external;
    function wethUpdatedEvent(address oldWETH, address newWETH) external;
    function protocolFeeUpdatedEvent(uint256 oldFee, uint256 newFee) external;
    function protocolTreasuryUpdatedEvent(address oldTreasury, address newTreasury) external;
    function oracleUpdatedEvent(address oldOracle, address newOracle) external;
    function honeyFactoryUpdatedEvent(address oldFactory, address newFactory) external;
    function rewardDistributorUpdatedEvent(address oldManager, address newManager) external;
    function eventEmitterUpdatedEvent(address oldEmitter, address newEmitter) external;
    function strategyAddressesAddedEvent(address[] memory strategyAddresses) external;
    function redistributorAddressesAddedEvent(address[] memory redistributorAddresses) external;
    function rewardsClaimerUpdatedEvent(address oldClaimer, address newClaimer) external;
    function strategyPauseUpdatedEvent(address strategy, bool oldState, bool newState) external;

    function setWhitelistAddress(address[] memory contractAddresses) external;
    function removeWhitelistAddress(address[] memory contractAddresses) external;

    function depositedEvent(
        address trancheVault,
        address account,
        address token,
        uint256 amount,
        uint256 depositAmount,
        uint256 depositAmountAfterSlippage,
        uint256 mintAmount,
        uint256 tid,
        uint256 currentRate,
        uint256 timestamp
    ) external;
    function withdrawnEvent(
        address trancheVault,
        address account,
        address token,
        uint256 tid,
        uint256 amount,
        uint256 balanceWithdrawn,
        uint256 currentRate,
        uint256 timestamp
    ) external;
    function feeWithdrawnEvent(address trancheVault, uint256 amount, uint256 timestamp) external;
    function trancheAddedEvent(address trancheVault, uint256 tid) external;
    function trancheStartedEvent(address trancheVault, uint256 tid, uint256 cycle, uint256 principal) external;
    function trancheSettledEvent(
        address trancheVault,
        uint256 tid,
        uint256 cycle,
        uint256 principal,
        uint256 capital,
        uint256 rate
    ) external;

    function strategyDepositFailedEvent(address strategyContractAddress) external;
    function strategyWithdrawalFailedEvent(address strategyContractAddress) external;
    function strategyInternalFunctionFailedEvent(
        address strategyContractAddress,
        string calldata functionName
    ) external;
    function strategyDepositSuccessEvent(address strategyContractAddress, uint256 amount) external;
    function strategyWithdrawSuccessEvent(address strategyContractAddress, uint256 amount) external;
    function stakeBgtEvent(address strategy, uint256 amount) external;
    function withdrawBgtEvent(address strategy, uint256 amount) external;
    function claimBgtRewardEvent(address[] memory strategies, uint256[] memory amounts) external;
    function juniorTokenBalanceUpdated(address token, uint256 amount) external;
    function investmentUpdatedEvent(
        address trancheVault,
        uint256 seniorVaultInvestments,
        uint256 juniorVaultInvestments,
        uint256 totalActualSeniorVaultInvestments,
        uint256 totalActualJuniorVaultInvestments,
        uint256 totalActualSeniorVaultInvestmentsAfterSlippage,
        uint256 totalActualJuniorVaultInvestmentsAfterSlippage,
        uint256 currentStrategyBalance,
        uint256 totalInvestment,
        uint256 seniorTokenSupply,
        uint256 juniorTokenSupply
    ) external;
    function deployTrancheVaultEvent(
        uint256 index,
        address trancheVault,
        address strategyManager,
        address vaultManagerConfig,
        address feeModule,
        address accessController,
        // address rewardsDistributor,
        address seniorToken,
        address juniorToken
    ) external;
    function upgradeStrategyManagerEvent(address newStrategyManager) external;
    function upgradeTrancheVaultEvent(address newTrancheVault) external;
    function strategiesAndRatiosChangedEvent(address strategyManager, bool value) external;
    function ratioChangedEvent(
        address strategyManager,
        address strategyAddress,
        uint256 ratioBefore,
        uint256 ratioAfter
    ) external;
    function rewardsAddedEvent(
        address rewardsDistributor,
        address[] memory users,
        address token,
        uint256 totalAmount
    ) external;
    function claimRewardsEvent(address rewardsDistributor, address user, address token, uint256 amount) external;
    function whitelistUpdated(address account, bool status) external;
    function upgradeFeeModuleEvent(address newFeeModule) external;
    function upgradeVaultManagerConfigEvent(address newVaultManagerConfig) external;
    function rewardMetadataUpdatedEvent(address token, bytes32 merkleRoot, uint256 updatedAt) external;
    function rewardClaimedEvent(
        address[] calldata tokens,
        address[] calldata accounts,
        uint256[] calldata amounts
    ) external;
    function strategyRewardClaimedEvent(address strategy, address[] memory tokens, uint256[] memory amounts, uint256 compoundedAmount, uint256 receiptTokenAmount, uint256 dustAmount) external;

    function strategyStateSetEvent(address strategy, bool isStrategy) external;
    function bgtStakeGaugeSetEvent(
        address strategy,
        address gauge,
        address receiptToken,
        address redistributorAddress,
        uint256 amount
    ) external;
    function validatorInfoSetEvent(
        bytes[] memory publicKey,
        uint256[] memory boostingRatio,
        uint256[] memory unboostingRatio
    ) external;
    function unboostDelayAndRequestTimeoutSetEvent(uint256 unboostDelay, uint256 requestTimeout) external;
    function beraClaimedEvent(address user, uint256 amount) external;

    /**
     * @notice Emits a protocol fee charged event
     * @param trancheVault Address of the tranche vault
     * @param totalProfit Total profit amount
     * @param protocolFee Protocol fee amount
     * @param vaultManagerFee Vault manager fee amount
     * @param newHighWaterMark New high water mark value
     */
    function protocolFeeChargedEvent(
        address trancheVault,
        uint256 totalProfit,
        uint256 protocolFee,
        uint256 vaultManagerFee,
        uint256 newHighWaterMark
    ) external;

    /**
     * @notice Emits a fee minted event
     * @param trancheVault Address of the tranche vault
     * @param recipient Address receiving the minted fee
     * @param amount Amount of fee minted
     */
    function feeMintedEvent(address trancheVault, address recipient, uint256 amount) external;

    /**
     * @notice Emits a performance fee charged event
     * @param trancheVault Address of the tranche vault
     * @param trancheId Tranche ID (0 = senior, 1 = junior)
     * @param profit Total profit amount
     * @param feeAmount Fee amount charged
     * @param newHwm New high water mark value
     */
    function performanceFeeChargedEvent(
        address trancheVault,
        uint256 trancheId,
        uint256 profit,
        uint256 feeAmount,
        uint256 newHwm
    ) external;

    /**
     * @notice Emits a fee parameters updated event
     * @param seniorEntryFee Senior tranche entry fee in basis points
     * @param juniorEntryFee Junior tranche entry fee in basis points
     * @param seniorExitFee Senior tranche exit fee in basis points
     * @param juniorExitFee Junior tranche exit fee in basis points
     * @param seniorExitFeePeriod Senior tranche exit fee period in seconds
     * @param juniorExitFeePeriod Junior tranche exit fee period in seconds
     * @param seniorPerformanceFee Senior tranche performance fee in basis points
     * @param juniorPerformanceFee Junior tranche performance fee in basis points
     */
    function feeParametersUpdatedEvent(
        uint256 seniorEntryFee,
        uint256 juniorEntryFee,
        uint256 seniorExitFee,
        uint256 juniorExitFee,
        uint256 seniorExitFeePeriod,
        uint256 juniorExitFeePeriod,
        uint256 seniorPerformanceFee,
        uint256 juniorPerformanceFee
    ) external;

    function feeParameterUpdatedEvent(bytes4 selector, uint256 oldValue, uint256 newValue) external;
    function vaultTreasuryUpdatedEvent(address oldTreasury, address newTreasury) external;
    function seniorRatePerBlockUpdatedEvent(uint256 oldRate, uint256 newRate) external;
    function entryFeeChargedEvent(
        address trancheVault,
        uint256 trancheId,
        uint256 grossAmount,
        uint256 feeAmount,
        uint256 netAmount
    ) external;
    function exitFeeChargedEvent(
        address trancheVault,
        address user,
        uint256 trancheId,
        uint256 grossAmount,
        uint256 feeAmount,
        uint256 netAmount
    ) external;
    function depositTimestampUpdatedEvent(
        address user,
        uint256 trancheId,
        uint256 oldTimestamp,
        uint256 newTimestamp
    ) external;
    function privilegedChangeScheduledEvent(bytes32 operation, uint256 readyAt) external;
    function privilegedChangeExecutedEvent(bytes32 operation) external;
    function privilegedChangeCancelledEvent(bytes32 operation) external;
    function privilegedChangeDelayUpdatedEvent(uint256 oldDelay, uint256 newDelay) external;


    /**
     * @notice Emits an added whitelisted user event
     * @param caller The address of the caller
     * @param users The array of whitelisted users
     */
    function addedWhitelistedUserEvent(address caller, address[] memory users) external;

    /**
     * @notice Emits a removed whitelisted user event
     * @param caller The address of the caller
     * @param users The array of whitelisted users
     */
    function removedWhitelistedUserEvent(address caller, address[] memory users) external;

    /**
     * @notice Emits a dust strategy changed event
     * @param strategyManager The address of the strategy manager
     * @param dustStrategy The address of the dust strategy
     */
    function dustStrategyChangedEvent(address strategyManager, address dustStrategy) external;

    /**
     * @notice Emits a strategy addresses removed event
     * @param strategyAddresses The array of strategy addresses
     */
    function strategyAddressesRemovedEvent(address[] memory strategyAddresses) external;
}
"
