pragma solidity 0.8.30;

import {FunctionParameters} from "../../library/core/FunctionParameters.sol";

interface ITrancheVault {
    function init(FunctionParameters.TrancheVaultInitializeParams calldata initData) external;

    function deposit(uint256 _wantAmt) external;

    function withdraw() external;

    function juniorToken() external view returns (address);

    function getTokenAddresses() external view returns (address, address);

    function currentTrancheInformation()
        external
        view
        returns (uint256, uint256, uint256, uint256, uint256, uint256, uint256, uint256, uint256);

    function mintSeniorTokenFee(address to, uint256 mintAmount) external;

    function mintJuniorTokenFee(address to, uint256 mintAmount) external;
}
"
