pragma solidity 0.8.30;

import {FunctionParameters} from "../../library/core/FunctionParameters.sol";

interface IVaultManagerConfig {
    function initialize(FunctionParameters.VaultManagerConfigInitializeParams calldata params) external;
    function getUserTreasury() external view returns (address);
    function getVaultManagerFee() external view returns (uint256);
