    function getVaultSwapSlippage() external view returns (uint256);
    function getVaultLpSlippage() external view returns (uint256);
    function getVaultTid() external view returns (uint256);
    function isDepositPausedState() external view returns (bool);
    function isWithdrawPausedState() external view returns (bool);
    function pauseDepositsFromVault() external;
}
